/* data.voucher carries everything needed to deliver.
 * Turn its base64 into a real binary for Gmail, Drive and WhatsApp. */
const v = $('Reservation confirmed').first().json.body.data.voucher;

if (!v.pdfBase64) {
  throw new Error(
    'No PDF in the payload. Tick "Also attach a ready-made PDF" in ' +
    'Fidato -> Admin -> Integrations and save, then create a booking.'
  );
}

return [{
  json: { filename: v.filename, reference: v.reference, to: v.to },
  binary: {
    data: {
      data: v.pdfBase64,
      mimeType: 'application/pdf',
      fileName: v.filename,
    },
  },
}];

/* ══════════════════════════════════════════════════════════════
   BUILD THE TEMPLATE PARAMETERS

   The approved template has 8 body variables, in this order:
     1 name_1     guest name
     2 hotel_id   booking reference
     3 hotel      property name
     4 ck_in      check-in
     5 ck_out     check-out
     6 rm_type    room type
     7 no_guest   guests
     8 crs_nom    contact number

   ⚠️ ORDER IS EVERYTHING. Interakt sends bodyValues positionally and
   Meta substitutes {{1}}..{{8}} by index — the names in the template
   are labels for humans, not keys. Reorder this array and every guest
   gets a booking reference where their name should be, with no error.

   ⚠️ META REJECTS EMPTY PARAMETERS, and it rejects newlines, tabs and
   runs of 4+ spaces inside one. A blank org phone or a room type with
   a line break fails the whole send with a generic error that names
   none of it. Everything below is coalesced and flattened.
   ══════════════════════════════════════════════════════════════ */

const d = $('Reservation confirmed').first().json.body.data;
const v = d.voucher;
const m = v.model;

/* Meta's constraints, applied to every parameter without exception. */
const clean = (value, fallback = '-') => {
  const text = String(value ?? '')
    .replace(/[\r\n\t]+/g, ' ')   // no line breaks inside a parameter
    .replace(/\s{4,}/g, ' ')       // no runs of four or more spaces
    .trim();
  return text === '' ? fallback : text;
};

/* Rooms are an array. One booking can hold several types, and the
   template has a single slot, so they are joined rather than silently
   showing only the first. */
const roomType = (m.rooms || [])
  .map((r) => `${r.quantity} x ${r.roomType}`)
  .join(', ');

const guests =
  `${m.totalAdults} adult${m.totalAdults === 1 ? '' : 's'}` +
  (m.totalChildren ? `, ${m.totalChildren} child${m.totalChildren === 1 ? '' : 'ren'}` : '');

/* ⚠️ Falls back to a literal number. org.phone comes from
   Admin -> Settings, which is blank on a fresh deployment — and an
   empty parameter fails the send outright rather than looking untidy.
   Put the real number in Settings; this only stops a silent failure. */
const crsNumber = clean(m.org?.phone, '+91 20 1234 5678');

/* Digits only, then peel the country code off. Interakt wants the two
   separately, while the CRS stores one human-typed string. */
const digits = String(v.guestPhone || '').replace(/\D/g, '');
let countryCode = '+91';
let phoneNumber = digits;
if (digits.length > 10) {
  countryCode = '+' + digits.slice(0, digits.length - 10);
  phoneNumber = digits.slice(-10);
}
if (phoneNumber.length !== 10) {
  throw new Error(
    `Guest phone "${v.guestPhone}" is not 10 digits after stripping the ` +
    'country code. WhatsApp will reject it.'
  );
}

/* Drive serves the file from this shape. Meta must be able to GET it
   with no credentials and receive the PDF itself, not an HTML page. */
const fileId = $('Save PDF to Drive').first().json.id;
const documentUrl = `https://drive.google.com/uc?export=download&id=${fileId}`;

return [{
  json: {
    countryCode,
    phoneNumber,
    documentUrl,
    filename: v.filename,
    reference: v.reference,
    bodyValues: [
      clean(m.guestName),      // 1 name_1
      clean(v.reference),      // 2 hotel_id
      clean(m.hotelName),      // 3 hotel
      clean(m.checkIn),        // 4 ck_in
      clean(m.checkOut),       // 5 ck_out
      clean(roomType),         // 6 rm_type
      clean(guests),           // 7 no_guest
      crsNumber,               // 8 crs_nom
    ],
  },
}];

parameters.jsonBody:
={{ JSON.stringify({
  countryCode: $json.countryCode,
  phoneNumber: $json.phoneNumber,
  callbackData: $json.reference,
  type: 'Template',
  template: {
    name: 'REPLACE_WITH_TEMPLATE_NAME',
    languageCode: 'en',
    headerValues: [ $json.documentUrl ],
    fileName: $json.filename,
    bodyValues: $json.bodyValues
  }
}) }}
